  const equipmentSystem = mp.game.ScriptGameInstance.GetScriptableSystemsContainer().Get('EquipmentSystem');
  if (!equipmentSystem) return false;

  equipmentSystem.EquipCyberwareByTDBID(player, itemKey);
  return true;
}

